import{_ as e,o as t,c as o,a3 as a}from"./chunks/framework.BWzgKoSO.js";const s="/incomplete-weight-loss-guide/images/shoes-door.png",g=JSON.parse('{"title":"尾声　你一定要瘦","description":"","frontmatter":{},"headers":[],"relativePath":"epilogue.md","filePath":"epilogue.md","lastUpdated":1793339289000}'),r={name:"epilogue.md"};function i(n,p,l,_,c,d){return t(),o("div",null,[...p[0]||(p[0]=[a('<h1 id="尾声-你一定要瘦" tabindex="-1">尾声　你一定要瘦 <a class="header-anchor" href="#尾声-你一定要瘦" aria-label="Permalink to &quot;尾声　你一定要瘦&quot;">​</a></h1><p>方法讲完了。这一页不讲方法。</p><p><strong>你一定要瘦。</strong></p><p>不是“想瘦就试试”，不是“能瘦一点是一点”。是真的瘦下来一次。</p><p>话说这么硬，是因为有些事你不瘦下来，别人讲一百遍，你也只是听过。</p><p>瘦下来你才知道身体轻是什么感觉。不是秤上那个数，是你上楼不再数还剩几层，蹲下去系鞋带不用先找姿势，坐在地上能自己站起来，夏天走一段路背上不湿。这些事你现在觉得没什么，轻了二十斤那天会突然发现，它们一直是舒服的。</p><p>瘦下来你才知道自己多大能力。你以为自己只能走两公里，走到第三公里发现腿没断；你以为自己管不住嘴，忍了三周发现没那么难。人没变，是你以前没试过。</p><p>我当初一公里跑不下来，跑一段走一段，气先不行。后来一点几公里，再后来三公里，最近五公里。没有哪一天是突然就能跑的，都是上一次多一点点，身体记住，下一次它就肯了。</p><p>所以别问“我能不能瘦”。这问题你现在答不上来，也没人能替你答。<strong>问你什么时候开始。</strong></p><p>不过这句话得有个边界，不然容易走歪。</p><p>“你一定要瘦”不是“你必须瘦到某个斤数”。斤数是你自己定的，不是别人替你定的。有人一百二十斤正好，有人一百三十五斤更好看，这不归秤管。</p><p>它的意思是：这件事你得亲手做成一次。做成一次，你以后对自己说的“我做不到”，分量就不一样。</p><p>我把它写成书，是因为我做过一次，也失败过一次。</p><p>19 岁那次我掉了 80 斤，那年我以为事情结束了——体重下去了，任务完成。后来那 80 斤一斤一斤回来，我才明白那只是上半场。</p><p>这一次，78 天，100.80 公斤到 74.65 公斤，上半场算打完了。下半场刚开始，我还没有结果可给你。</p><p>这本书写的是我正在走的路，不是我走完的路。哪里有问题，你去仓库提一个 issue，我核到一手来源就改，改了什么会记在修订记录里。</p><p><img src="'+s+'" alt="门口的一双跑鞋"></p><p>轻盈这件事，得自己走一遍才知道。</p><hr><p>Simonlin 公众号：Simonlin的精神世界</p>',20)])])}const u=e(r,[["render",i]]);export{g as __pageData,u as default};
